const item = $input.first().json;
let texto = item.output ?? '';

// WhatsApp só reconhece *negrito* (um asterisco) e _itálico_ (um underline).
// O modelo às vezes escreve **negrito**/__itálico__ (markdown padrão) mesmo
// com a instrução no prompt -- corrige aqui de forma determinística, sem
// depender só do modelo obedecer.
texto = texto.replace(/\*\*(.+?)\*\*/g, '*$1*');
texto = texto.replace(/__(.+?)__/g, '_$1_');

// Garante que valor em R$ sempre tenha os centavos (",00") -- o modelo às
// vezes escreve "R$ 500" sem casas decimais.
texto = texto.replace(/R\$\s*\d{1,3}(?:\.\d{3})*(?:,\d{2})?/g, (m) => {
  const numero = m.replace(/^R\$\s*/, '');
  return 'R$ ' + (/,\d{2}$/.test(numero) ? numero : numero + ',00');
});

// WhatsApp reconhece sequências de dígitos (ex.: "870" ou "1.200") como se
// fossem telefone/código e deixa parte do valor sublinhada/colorida, tocável
// -- quebra a sequência com um caractere invisível (zero-width space) logo
// após o primeiro dígito, sem mudar o que aparece pro usuário.
texto = texto.replace(/R\$\s*(\d)(\d{0,2}(?:\.\d{3})*,\d{2})/g, 'R$ $1\u200b$2');

// Remove qualquer divisor de linha inteira ("---" ou o antigo ▬▬▬▬) que o
// modelo ainda tente colocar entre cursos -- o prompt já pede só linha em
// branco entre eles, sem divisor.
texto = texto.replace(/^[ \t]*(-{3,}|▬{3,})[ \t]*\n?/gm, '');

return [{ json: { ...item, output: texto } }];

const data = $input.first().json;
const sel = data.body.listResponseMessage;

const contextos = {
  financeiro: 'O usuário selecionou situação financeira. Solicite o CPF para consultar boletos em aberto.',
  secretaria: 'O usuário selecionou Secretaria (assunto de quem já é aluno matriculado). Pergunte o que precisa: documentos, declarações, prazos ou outro assunto administrativo. Se na verdade a pessoa ainda não é aluna e quer se matricular, trate como lead novo (fluxo de CRM/cursos), não como Secretaria.',
  ti: 'O usuário selecionou Suporte TI. Pergunte qual problema está tendo: acesso ao portal, senha, email ou outro sistema.',
  avisos: 'O usuário selecionou avisos da escola. Mostre os comunicados ativos usando a ferramenta disponível.',
  calendario: 'O usuário selecionou calendário. Mostre os próximos eventos usando a ferramenta disponível.',
  matricula: 'O usuário demonstrou interesse em se matricular. Use a tool "Verificar Lead CRM" para ver se já está cadastrado. Se não, colete nome completo, email e telefone para registrar o lead.',
};

const mensagem = contextos[sel?.selectedRowId] || `O usuário selecionou: ${sel?.title}`;

return [{ json: { ...data, body: { ...data.body, text: { message: mensagem } } } }];

const cpfData = $input.first().json;
const webhook = $('Webhook').first().json;
const msg = webhook.body.text.message;

let enriched = msg;

if (cpfData.cpf && !cpfData.error && !cpfData.message) {
  enriched = `[Sistema: CPF: ${cpfData.cpf}${cpfData.nomeResponsavel ? `, responsável: ${cpfData.nomeResponsavel}` : ''}${cpfData.tipo ? `, tipo: ${cpfData.tipo}` : ''}${cpfData.email ? `, email: ${cpfData.email}` : ''}. Use-o diretamente sem pedir ao usuário, mas NUNCA diga ao usuário que você já sabe o CPF dele nem mencione ter esse dado -- se o assunto não for pagamento/boleto/mensalidade, aja como se não soubesse.]\n\n${msg}`;
}

return [{ json: { ...webhook, body: { ...webhook.body, text: { message: enriched } } } }];

const cpfData = $input.first().json;
const mapped = $('Mapear Seleção do Menu').first().json;
const msg = mapped.body.text.message;

let enriched = msg;

if (cpfData.cpf && !cpfData.error && !cpfData.message) {
  enriched = `[Sistema: CPF: ${cpfData.cpf}${cpfData.nomeResponsavel ? `, responsável: ${cpfData.nomeResponsavel}` : ''}${cpfData.tipo ? `, tipo: ${cpfData.tipo}` : ''}${cpfData.email ? `, email: ${cpfData.email}` : ''}. Use-o diretamente sem pedir ao usuário, mas NUNCA diga ao usuário que você já sabe o CPF dele nem mencione ter esse dado -- se o assunto não for pagamento/boleto/mensalidade, aja como se não soubesse.]\n\n${msg}`;
}

return [{ json: { ...mapped, body: { ...mapped.body, text: { message: enriched } } } }];

